"""Sort semantic version strings by SemVer 2.0.0 precedence."""


def _identifier_key(identifier):
    """Numeric identifiers sort before alphanumeric ones; each group
    compares internally by integer value or ASCII order."""
    if identifier.isdigit():
        return (0, int(identifier), "")
    return (1, 0, identifier)


def _precedence_key(version):
    """Build a comparison key for a SemVer string.

    Build metadata (after '+') is ignored. A version with no pre-release
    gets a pre-release component that sorts above every pre-release.
    """
    core_and_pre = version.split("+", 1)[0]
    if "-" in core_and_pre:
        core, pre = core_and_pre.split("-", 1)
    else:
        core, pre = core_and_pre, None

    major, minor, patch = (int(part) for part in core.split("."))

    if pre is None:
        pre_key = (1,)
    else:
        pre_key = (0, tuple(_identifier_key(p) for p in pre.split(".")))

    return (major, minor, patch, pre_key)


def sort_versions(vs):
    """Return the versions sorted lowest precedence first.

    Versions that compare equal keep their input order (sorted is stable).
    """
    return sorted(vs, key=_precedence_key)
